final class DraconicCrucibleCraftingJeiCategory
extends DraconicCrucibleJeiCategory<DraconicCrucibleShapedRecipe> {
    DraconicCrucibleCraftingJeiCategory(IGuiHelper guiHelper, RecipeType<DraconicCrucibleShapedRecipe> recipeType) {
        super(guiHelper, recipeType, "jei.saintsdragons.draconic_crucible.crafting");
    }

    public void setRecipe(IRecipeLayoutBuilder builder, DraconicCrucibleShapedRecipe recipe, IFocusGroup focuses) {
        int offsetX = (3 - recipe.width()) / 2;
        int offsetY = (3 - recipe.height()) / 2;
        for (int row = 0; row < recipe.height(); ++row) {
            for (int column = 0; column < recipe.width(); ++column) {
                Ingredient ingredient = (Ingredient)recipe.m_7527_().get(column + row * recipe.width());
                if (ingredient.m_43947_()) continue;
                builder.addInputSlot(62 + (offsetX + column) * 18, 60 + (offsetY + row) * 18).addIngredients(ingredient);
            }
        }
        builder.addOutputSlot(80, 21).addItemStack(recipe.result());
        this.addFuelSlot(builder, recipe.requiredHeatLevel());
    }

    @Override
    protected int requiredHeatLevel(DraconicCrucibleShapedRecipe recipe) {
        return recipe.requiredHeatLevel();
    }

    @Override
    protected int processingTime(DraconicCrucibleShapedRecipe recipe) {
        return recipe.processingTime();
    }
}

