protected final void addFuelSlot(IRecipeLayoutBuilder builder, int requiredHeatLevel) {
    IRecipeSlotBuilder fuelSlot = builder.addSlot(RecipeIngredientRole.CATALYST, 30, 91).setSlotName("fuel");
    for (DraconicCrucibleFuelTier tier : DraconicCrucibleFuelTier.values()) {
        if (!tier.canProcess(requiredHeatLevel) || tier.tag() == null) continue;
        fuelSlot.addIngredients(Ingredient.m_204132_(tier.tag()));
    }
    fuelSlot.addRichTooltipCallback((recipeSlotView, tooltip) -> tooltip.add((FormattedText)Component.m_237110_((String)"gui.saintsdragons.draconic_crucible.valid_fuel", (Object[])new Object[]{requiredHeatLevel})));
}

public final void draw(T recipe, IRecipeSlotsView recipeSlotsView, GuiGraphics guiGraphics, double mouseX, double mouseY) {
    this.background.draw(guiGraphics);
    int heatLevel = Math.max(1, Math.min(3, this.requiredHeatLevel(recipe)));
    double progress = DraconicCrucibleJeiCategory.getLoopProgress(this.processingTime(recipe));
    DraconicCrucibleUiLayout.GaugeAnimation gauge = DraconicCrucibleUiLayout.gaugeAnimationForHeatLevel(heatLevel);
    int gaugeHeight = gauge.finalHeight() + (int)Math.round((double)(gauge.initialHeight() - gauge.finalHeight()) * (1.0 - progress));
